bool PageStubDispatch::AcceptWithResponder(
    Page* impl,
    mojo::Message* message,
    std::unique_ptr<mojo::internal::ResponderThunk> responder) {
  [[maybe_unused]] const bool message_is_sync =
      message->has_flag(mojo::Message::kFlagIsSync);
  [[maybe_unused]] const uint64_t request_id = message->request_id();
  switch (static_cast<messages::Page>(message->header()->name)) {
    case messages::Page::kOnShow: {
      break;
    }
    case messages::Page::kOnContextMenuClosed: {
      break;
    }
    case messages::Page::kSetInputState: {
      break;
    }
    case messages::Page::kSetFocus: {
      break;
    }
    case messages::Page::kClearAutocompleteMatches: {
      break;
    }
    case messages::Page::kClearPopup: {
      internal::Page_ClearPopup_Params_Data* params =
          reinterpret_cast<
              internal::Page_ClearPopup_Params_Data*>(
                  message->mutable_payload());
      

      // Validation for Page.5
      bool success = true;
      Page_ClearPopup_ParamsDataView input_data_view(params, message);
      
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            Page::Name_, 5, false);
        return false;
      }
      auto callback =
          Page_ClearPopup_ProxyToResponder::CreateCallback(
              *message, std::move(responder));
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->ClearPopup(std::move(callback));
      return true;
    }
    case messages::Page::kSetDefaultSearchProvider: {
      break;
    }
    case messages::Page::kFocusSearchWithDefaultSearchEngineKeywordMode: {
      break;
    }
  }
  return false;
}
