// static
bool StructTraits<::omnibox_popup::mojom::OmniboxInputState::DataView, ::omnibox_popup::mojom::OmniboxInputStatePtr>::Read(
    ::omnibox_popup::mojom::OmniboxInputState::DataView input,
    ::omnibox_popup::mojom::OmniboxInputStatePtr* output) {
  bool success = true;
  ::omnibox_popup::mojom::OmniboxInputStatePtr result(::omnibox_popup::mojom::OmniboxInputState::New());
  
      if (success)
        result->sequence_number = input.sequence_number();
      if (success)
        result->tab_id = input.tab_id();
      if (success && !input.ReadText(&result->text))
        success = false;
      if (success && !input.ReadSelection(&result->selection))
        success = false;
      if (success)
        result->user_input_in_progress = input.user_input_in_progress();
      if (success && !input.ReadFullUrl(&result->full_url))
        success = false;
      if (success)
        result->is_focused = input.is_focused();
      if (success && !input.ReadPermanentDisplayText(&result->permanent_display_text))
        success = false;
      if (success)
        result->show_full_url = input.show_full_url();
      if (success && !input.ReadMatchesUpdate(&result->matches_update))
        success = false;
      if (success && !input.ReadKeywordModel(&result->keyword_model))
        success = false;
      if (success)
        result->is_tab_switch = input.is_tab_switch();
      if (success && !input.ReadUrlEmphasis(&result->url_emphasis))
        success = false;
      if (success && !input.ReadUnelidedUrlEmphasis(&result->unelided_url_emphasis))
        success = false;
      if (success && !input.ReadCurrentMatch(&result->current_match))
        success = false;
  *output = std::move(result);
  return success;
}

